APPROVED_METADATA_ANCHOR = '7b39fb5fbda0cdf8d74eace7bca482e33378083dd1c3960ee82b426e9ef8723f'
APPROVED_SELF_AST = 'f77c8f5e0707ce368bf26d8a83f868d945cadb4d244e3de2eb4fc86ec174c877'

def restore_reviewed_parent_source(source, relative):
    own = Path(__file__)
    fresh_source = own.read_text(encoding='utf-8')
    tree = ast.parse(fresh_source)
    names = ('REVIEWED_EDITS', 'APPROVED_METADATA_ANCHOR', 'APPROVED_SELF_AST')
    fresh = {}
    for name in names:
        declarations = [n for n in tree.body if type(n) is ast.Assign and len(n.targets) == 1
                        and type(n.targets[0]) is ast.Name and n.targets[0].id == name]
        if len(declarations) != 1:
            raise ValueError('Management reuse compatibility declaration shape differs')
        fresh[name] = ast.literal_eval(declarations[0].value)
    if fresh != dict(zip(names, (REVIEWED_EDITS, APPROVED_METADATA_ANCHOR, APPROVED_SELF_AST))):
        raise ValueError('Management reuse compatibility loaded and fresh metadata differs')
    for node in tree.body:
        if type(node) is ast.Assign and len(node.targets) == 1 and type(node.targets[0]) is ast.Name:
            if node.targets[0].id in names:
                node.value = ast.Constant(None)
    if sha256(ast.unparse(tree).encode()).hexdigest() != APPROVED_SELF_AST:
        raise ValueError('Management reuse compatibility envelope differs')
    if sha256(json.dumps(REVIEWED_EDITS, sort_keys=True, separators=(',', ':')).encode()).hexdigest() != APPROVED_METADATA_ANCHOR:
        raise ValueError('Management reuse compatibility metadata anchor differs')
    recipe = REVIEWED_EDITS.get(relative.removeprefix('src/'))
    if recipe is None:
        if own.read_text(encoding='utf-8') != fresh_source:
            raise ValueError('Management reuse compatibility changed during restoration')
        return source
    if sha256(ast.unparse(ast.parse(source)).encode()).hexdigest() != recipe['current_ast']:
        if own.read_text(encoding='utf-8') != fresh_source:
            raise ValueError('Management reuse compatibility changed during restoration')
        return source
    restored = source
    for current, previous in recipe['edits']:
        if not current or restored.count(current) != 1:
            raise ValueError('Management reuse compatibility exact reviewed edit differs: ' + relative)
        restored = restored.replace(current, previous, 1)
    if sha256(ast.unparse(ast.parse(restored)).encode()).hexdigest() != recipe['parent_ast']:
        raise ValueError('Management reuse compatibility retained parent AST differs: ' + relative)
    if own.read_text(encoding='utf-8') != fresh_source:
        raise ValueError('Management reuse compatibility changed during restoration')
    return restored


def certify_retained_waiting_ladder_source():
    """Bind reviewed current source and the unchanged waiting approval separately.

    This composition never calls a catalog certifier and never substitutes
    restored text for runtime reads. Restoration proves retained declarations;
    the current closure independently proves the actual executing modules.
    """
    from . import backtest_fixed_structural_lot_certification_v20 as current
    root = Path(__file__).resolve().parents[2]
    paths = tuple(root / relative for relative in current.REQUIRED_SOURCE_FILES)
    paths = (*paths, Path(current.__file__))
    snapshots = tuple((path, path.read_text(encoding='utf-8')) for path in paths)
    current_proof = current.certify_fixed_structural_lot_source()
    prior_path = root / 'src/backend/backtest_declared_waiting_ladder_certification.py'
    prior_source = prior_path.read_text(encoding='utf-8')
    prior_tree = ast.parse(prior_source)
    declarations = {}
    names = ('REQUIRED_SOURCE_FILES', 'REVIEWED_SOURCE_AST', 'PENDING_SOURCE_REVIEWS',
             'APPROVED_METADATA_ANCHOR', 'APPROVED_SELF_AST')
    for name in names:
        selected = [n for n in prior_tree.body if type(n) is ast.Assign and len(n.targets) == 1
                    and type(n.targets[0]) is ast.Name and n.targets[0].id == name]
        if len(selected) != 1:
            raise ValueError('Retained waiting approval declarations differ')
        declarations[name] = ast.literal_eval(selected[0].value)
    if declarations['PENDING_SOURCE_REVIEWS']:
        raise ValueError('Retained waiting source reviews remain unapproved')
    observed = [('certifier_envelope', declarations['APPROVED_SELF_AST']),
                ('certifier_metadata', declarations['APPROVED_METADATA_ANCHOR'])]
    retained_snapshots = [(prior_path, prior_source)]
    for relative in declarations['REQUIRED_SOURCE_FILES']:
        path = root / relative
        source = path.read_text(encoding='utf-8')
        restored = restore_reviewed_parent_source(source, relative)
        tree = ast.parse(restored)
        expected = declarations['REVIEWED_SOURCE_AST'][relative]
        if type(expected) is dict:
            for symbol, digest in expected.items():
                nodes = [n for n in tree.body if type(n) is ast.FunctionDef and n.name == symbol]
                if len(nodes) != 1 or sha256(ast.unparse(nodes[0]).encode()).hexdigest() != digest:
                    raise ValueError('Retained waiting symbol restoration differs: ' + relative)
        elif sha256(ast.unparse(tree).encode()).hexdigest() != expected:
            raise ValueError('Retained waiting whole-source restoration differs: ' + relative)
        observed.append((relative, sha256(restored.encode()).hexdigest()))
        retained_snapshots.append((path, source))
    if any(path.read_text(encoding='utf-8') != source
           for path, source in (*snapshots, *retained_snapshots)):
        raise ValueError('Current or retained waiting source changed during composition')
    retained_proof = sha256(json.dumps(observed, separators=(',', ':')).encode()).hexdigest()
    return sha256(json.dumps((current_proof, retained_proof), separators=(',', ':')).encode()).hexdigest()
